import{_ as o,h as i,i as e,c as s,v as r,p as d,x as l,m as n,e as p,S as h}from"./chunks/framework.Dvtg8yj2.js";const A=JSON.parse('{"title":"世界模型四件事：重建、生成、仿真、交互","description":"","frontmatter":{"title":"世界模型四件事：重建、生成、仿真、交互","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/world-model-four-roles.md","filePath":"llm/world-model-four-roles.md","lastUpdated":1788454257000}'),m={name:"llm/world-model-four-roles.md"};function E(_,a,c,B,u,b){const t=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="世界模型四件事-重建、生成、仿真、交互" tabindex="-1">世界模型四件事：重建、生成、仿真、交互 <a class="header-anchor" href="#世界模型四件事-重建、生成、仿真、交互" aria-label="Permalink to &quot;世界模型四件事：重建、生成、仿真、交互&quot;">​</a></h1><div class="epigraph"><p>世界模型应当重建、生成并仿真三维世界，并让人与智能体都能与之交互。</p><footer>—— World Labs，Marble 产品博文中的世界模型职责表述</footer></div><p>「世界模型」若只当形容词，什么系统都能自称。World Labs 在 Marble 的公开叙述里把职责收成四件可分开检验的事：重建、生成、仿真、交互。四件事共用「三维世界」这个对象，但输入、输出和失败模式不同。重建回答「观测里已经有的东西如何变成一致的三维」；生成回答「没观测到的如何补上、纯语言如何长成世界」；仿真回答「世界随时间与力如何变」；交互回答「人与智能体如何在其中做事」。本篇把四件事分开写清，不把其中一件的成功说成另外三件已经完成。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>计算机视觉长期把重建当成独立学科：多视图几何、神经辐射场、高斯溅射，目标是给定足够观测，恢复可渲染的三维。计算机图形学把生成与仿真分开：生成可以是程序化场景或艺术家资产，仿真是刚体、流体、光照的前向过程。机器人把交互当成闭环：观测—规划—控制。生成式模型兴起之后，这四条线被压进同一个词。若不拆开，评测会错位：一段好看的新视角视频既可能来自重建（观测足够、模型在插值），也可能来自生成（观测不足、模型在编造），还可能根本没有可交互的状态。</p><p>拆开的实践理由是产品边界。一个系统可以擅长从几张照片抬出房间（重建），却不会在用户说「改成雨夜」时保持家具布局（生成加约束）。它可以导出漂亮的静态世界，却不能让杯子掉下桌沿（仿真）。它可以让人漫游，却不能让策略在其中学习（交互的对象仍是人，不是智能体）。World Labs 把四件事并列写出，是为了让「朝空间智能走」有可拆的里程碑，而不是一个含糊的大模型口号。</p><h3 id="失败应当对号入座" tabindex="-1">失败应当对号入座 <a class="header-anchor" href="#失败应当对号入座" aria-label="Permalink to &quot;失败应当对号入座&quot;">​</a></h3><p>重建失败表现为多视图不一致、尺度漂移、看不见的背面乱长。生成失败表现为提示对齐差、风格崩、无中生有的物体破坏已有结构。仿真失败表现为穿透、能量不守恒、时间一长场景解体。交互失败表现为延迟过高、状态不能累积、或智能体没有可读写的接口。四类失败不应用同一句「世界模型还不够好」带过。</p><p><span class="marginnote">RTFM 的叙述里写过：输入视角多时任务更像重建，视角少时必须外推，更像生成。这是同一套学习渲染器上的连续谱，但不能因此取消分类——谱的两端评测集不同，用户预期也不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="重建-观测约束下的三维提升" tabindex="-1">重建：观测约束下的三维提升 <a class="header-anchor" href="#重建-观测约束下的三维提升" aria-label="Permalink to &quot;重建：观测约束下的三维提升&quot;">​</a></h3><p>重建的输入是带空间意义的观测：多图、视频、深度、已知位姿或可估计位姿。输出是与观测相容的世界 \\(W_{\\mathrm{rec}}\\)，使得在已见位姿 \\(T_i\\) 上</p> \\[R(W_{\\mathrm{rec}}, T_i) \\approx I_i. \\]<p>未见到的区域可以保持不确定，或用弱先验填成可漫游的空洞，但必须标明：那是补全，不是测量。Marble 把多图、视频、真实场所的照片抬成可导出的三维世界，落在重建这一侧；观测越重叠、位姿越清楚，越应向测量靠拢。</p><h3 id="生成-在约束不足时发明世界" tabindex="-1">生成：在约束不足时发明世界 <a class="header-anchor" href="#生成-在约束不足时发明世界" aria-label="Permalink to &quot;生成：在约束不足时发明世界&quot;">​</a></h3><p>生成的输入可以是文本、单图、粗布局，或重建留下的空洞。输出 \\(W_{\\mathrm{gen}}\\) 只需满足提示与风格，不必对应某个真实房间。单图或短文本出完整场景时，模型必须发明相机没看到的墙面与家具背面——这是生成，即使管道看起来像「图生三维」。把生成误写成重建，会在数字孪生场景里造成法律责任：用户以为是扫描，实际是想象。</p><h3 id="仿真-状态的时间前向" tabindex="-1">仿真：状态的时间前向 <a class="header-anchor" href="#仿真-状态的时间前向" aria-label="Permalink to &quot;仿真：状态的时间前向&quot;">​</a></h3><p>仿真需要动力学。记状态 \\(W_t\\) 与行动 \\(a_t\\)，</p> \\[W_{t+1}=f(W_t, a_t). \\]<p>\\(f\\) 可以是可微物理、学习到的预测器，或二者的混合。没有 \\(f\\)，世界只有姿态，没有过程。生成式产品今天常常用「增强视频里的烟与水」冒充仿真：那是在二维时间轴上加动态纹理，不是在 \\(W\\) 上积分。真仿真应允许查询「若此时推这把椅子」的下一状态，并且下一状态仍是同一套三维表示。</p><h3 id="交互-人与智能体的读写接口" tabindex="-1">交互：人与智能体的读写接口 <a class="header-anchor" href="#交互-人与智能体的读写接口" aria-label="Permalink to &quot;交互：人与智能体的读写接口&quot;">​</a></h3><p>交互是在 \\(W\\) 上定义可读可写的操作：移动相机、编辑物体、施加力、获取传感器读数。人的交互强调延迟与可控编辑；智能体的交互强调稳定的观测空间与可重复的回合。Marble 的公开路线把「让人与智能体以新方式与生成世界交互」写成后续机会，等于承认当前交付偏创建与导出，交互尤其是智能体侧尚未与前三件同等成熟。</p>',22)),(e(),d(h,null,{default:l(()=>[p(t,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20REC%5B%22%E9%87%8D%E5%BB%BA%20%E8%A7%82%E6%B5%8B%E5%88%B0%E4%B8%89%E7%BB%B4%22%5D%20--%3E%20W%5B%22%E4%B8%96%E7%95%8C%E7%8A%B6%E6%80%81%20W%22%5D%0A%20%20GEN%5B%22%E7%94%9F%E6%88%90%20%E6%8F%90%E7%A4%BA%E5%88%B0%E4%B8%89%E7%BB%B4%22%5D%20--%3E%20W%0A%20%20W%20--%3E%20SIM%5B%22%E4%BB%BF%E7%9C%9F%20%E7%8A%B6%E6%80%81%E9%9A%8F%E6%97%B6%E9%97%B4%E6%9B%B4%E6%96%B0%22%5D%0A%20%20W%20--%3E%20INT%5B%22%E4%BA%A4%E4%BA%92%20%E4%BA%BA%E4%B8%8E%E6%99%BA%E8%83%BD%E4%BD%93%E8%AF%BB%E5%86%99%22%5D%0A%20%20SIM%20--%3E%20W%0A%20%20INT%20--%3E%20SIM%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>四件事的耦合方向不是对称的。重建给生成提供锚：真实照片约束了已见部分，生成只填其余。生成给重建提供先验：稀疏视角时纯几何会失败，生成填上可接受的背面。仿真依赖前两者给出的可占据几何，否则碰撞没有对象。交互依赖仿真或至少依赖持久状态，否则每次操作都在新采样一个世界，谈不上闭环。</p><p>机制上应用不同的损失。重建应对已见视图的光度或几何误差负责。生成应对提示符合度与未约束区域的合理性负责。仿真应对未来观测或物理残差负责。交互应对任务成功与延迟负责。把四项加进同一个扩散损失而不加权、不分工，训练信号会互相淹没：模型会优先把像素变好看，因为那一项梯度最密。</p><p><span class="marginnote">「可漫游」经常被算进交互。更准确的说法是：自由相机证明表示支持新视角查询，属于重建/生成质量的下游；交互还要求对象可操作、状态可累积。只飞相机，没有改变世界。</span></p><h3 id="同一资产上的角色切换" tabindex="-1">同一资产上的角色切换 <a class="header-anchor" href="#同一资产上的角色切换" aria-label="Permalink to &quot;同一资产上的角色切换&quot;">​</a></h3><p>一个导出的高斯溅射可以先当重建结果（对输入照片负责），再当生成结果（对文本风格负责），但要进仿真必须另接碰撞体，要进机器人必须再定义传感器。角色切换是显式的工程步骤，不是表示自动获得新能力。后文会分别写导出与网格；此处只需记住：换角色就要换接口与评测，不要假设「已经是世界模型了」四件事齐活。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用生成分数代替重建精度。数字孪生、测绘、取证需要重建合同：误差应相对测量，而不是相对美学。反过来，概念设计、游戏概念图需要生成合同：过度坚持照片测量会让模型不敢发明。仿真合同更贵：要时间步、要稳定积分，不能靠一条短视频演示。交互合同最容易超卖：浏览器里转一圈不等于机器人能在其中练策略。</p><p>World Labs 把 Marble 写成生成式世界产品，能力叙述覆盖从多种输入创建、编辑、扩展与导出；仿真与智能体交互被明确放在更向前的世界模型议程。读四件事时，应把「应当」和「已经上线」分开。RTFM 用学习渲染器在实时帧上同时擦到重建与生成的谱，仍几乎不提供可导出的物理仿真体。四件事是职责分解，不是每一个产品四格都打满。</p><p>另一条边界是评测集。重建有多视图基准；生成有提示符合与多样性；仿真有物理一致性与长期稳定；交互有任务成功与人机延迟。混用基准会让论文或博客看起来全面，工程上却无法决定下一周改哪一项损失。</p><p><span class="marginnote">四件事里最容易被视频模型吞掉的是仿真与交互。下一帧预测可以看起来像动力学，却不能保证行动可逆、状态可保存。需要单独的状态接口，而不是更长的视频。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>世界模型的四件事是重建、生成、仿真、交互，应分开定义、分开评测。</li><li>重建对已见观测负责；生成对提示与未观测补全负责。</li><li>仿真是状态的时间前向 \\(W_{t+1}=f(W_t,a_t)\\)；没有动力学就没有仿真。</li><li>交互是人与智能体对同一世界的读写；可漫游只是新视角查询，不等于可操作。</li><li>四件事耦合但不互相蕴含：导出漂亮三维不自动带来物理与智能体接口。</li><li>出处：World Labs，<em>Marble: A Multimodal World Model</em> 中的职责表述；RTFM 博文中重建/生成谱与实时交互的对照。不要把产品路线图上的「应当」写成已经交付的能力。</li></ul>',13))])}const q=o(m,[["render",E]]);export{A as __pageData,q as default};
